"""Write ``test/nn.torch.reference.generated.ts``: a torch-trained perceptron's
state dict (``torch.save``'s bytes), the ``NetType`` that states the same
network, the name map between them, a batch and torch's outputs — so
``test/nn.spec.ts`` holds ``nn_import_torch`` on both runners to running what
torch trained (east-workspace#1357 R28).

Run from this package::

    uv run --package elaraai-east-py-datascience python tests/fixtures/make_nn_torch_reference.py
"""

from __future__ import annotations

import io
import sys
from pathlib import Path

import numpy as np
import torch
from east import some
from east.types.types import FloatType, IntegerType, StringType
from east.types.values import EastArray, EastDict, EastStruct, EastVariant, EastVector

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import nn_families as fam  # noqa: E402
from east_py_datascience.nn.types import NnValueType  # noqa: E402
from make_nn_reference import ts  # noqa: E402

OUT = Path(__file__).resolve().parents[2] / "test" / "nn.torch.reference.generated.ts"


def main() -> None:
    torch.manual_seed(3)
    model = torch.nn.Sequential(torch.nn.Linear(3, 5), torch.nn.Tanh(), torch.nn.Linear(5, 2))
    # a few steps of training, so the weights are torch's own, not an init
    opt = torch.optim.SGD(model.parameters(), lr=0.1)
    g = torch.Generator().manual_seed(4)
    for _ in range(20):
        x = torch.randn(16, 3, generator=g)
        loss = ((model(x) - (x[:, :2] * 0.5)) ** 2).mean()
        opt.zero_grad()
        loss.backward()
        opt.step()
    buf = io.BytesIO()
    torch.save(model.state_dict(), buf)
    blob = buf.getvalue()

    net = fam.net(
        {"x": fam.spec("float", 2)},
        {
            "w1": fam.param([5, 3], "zeros"), "b1": fam.param([5], "zeros", decay=0.0),
            "w2": fam.param([2, 5], "zeros"), "b2": fam.param([2], "zeros", decay=0.0),
        },
        {},
        [
            fam.node("h0", fam.op("linear", x="x", weight="w1", bias=some("b1"))),
            fam.node("h", fam.unary("tanh", "h0")),
            fam.node("y", fam.op("linear", x="h", weight="w2", bias=some("b2"))),
        ],
        {"y": "y"},
    )
    names = {"w1": "0.weight", "b1": "0.bias", "w2": "2.weight", "b2": "2.bias"}
    x = torch.randn(4, 3, generator=g)
    with torch.no_grad():
        y = model(x)
    batch = fam.east_batch({"x": fam.tensor(x.numpy())})
    out = EastDict(StringType, NnValueType, {
        "y": EastVariant("float", EastStruct({
            "shape": EastArray(IntegerType, [int(d) for d in y.shape]),
            "data": EastVector.from_numpy(y.numpy().reshape(-1).astype(np.float64), FloatType),
        })),
    })
    parts = [
        "/**\n * Copyright (c) 2025 Elara AI Pty Ltd\n * Dual-licensed under AGPL-3.0 and commercial license. See LICENSE for details.\n */\n",
        "// Generated by tests/fixtures/make_nn_torch_reference.py — do not edit. A\n"
        "// torch-trained perceptron: its state dict as torch.save wrote it, the\n"
        "// NetType stating the same network, the weight → torch name map, a batch\n"
        "// and torch's outputs. nn.spec.ts holds nn_import_torch on both runners\n"
        "// to them.\n",
        'import { variant, some, type ValueTypeOf } from "@elaraai/east";\n'
        'import { NetType, NnBatchType } from "@elaraai/east-py-datascience";\n\n',
        "/** torch.save's bytes: the trained model's state dict. */\n"
        f"export const stateDict: Uint8Array = new Uint8Array([{', '.join(str(b) for b in blob)}]);\n\n",
        f"/** The same network as data. */\nexport const net: ValueTypeOf<typeof NetType> = {ts(fam.east_net(net), 0)};\n\n",
        "/** Weight name → torch name. */\nexport const names: Map<string, string> = new Map([\n"
        + "".join(f'    ["{k}", "{v}"],\n' for k, v in names.items()) + "]);\n\n",
        f"/** A batch, and what torch answered for it. */\nexport const batch: ValueTypeOf<typeof NnBatchType> = {ts(batch, 0, 'ValueTypeOf<typeof NnBatchType> extends Map<string, infer V> ? V : never')};\n\n",
        f"export const outputs: ValueTypeOf<typeof NnBatchType> = {ts(out, 0, 'ValueTypeOf<typeof NnBatchType> extends Map<string, infer V> ? V : never')};\n",
    ]
    OUT.write_text("".join(parts))
    print(f"wrote {OUT} ({OUT.stat().st_size // 1024} KB, {len(blob)} blob bytes)")


if __name__ == "__main__":
    main()
